module HeapProbability (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [31:0] b0,b1,b2,b3,b4,b5,b6,b7,\n    input [7:0] p0,p1,p2,p3,p4,p5,p6,p7,\n    output reg [31:0] result,\n    output reg done\n);\n\n    localparam MOD = 32'd1000000007;\n    localparam [2:0] S_IDLE = 3'd0,\n                     S_LOAD  = 3'd1,\n                     S_CHILD = 3'd2,\n                     S_TOP = 3'd3,\n                     S_PROCESS = 3'd4,\n                     S_COMPUTE = 3'd5,\n                     S_DONE = 3'd6;\n\n    reg [2:0] state, next_state;\n    reg [7:0] node_idx;\n    reg [7:0] max_node;\n    reg [7:0] children [0:7][0:7];\n    reg [7:0] child_cnt [0:7];\n    reg [31:0] b_vals [0:7];\n    reg [7:0] parents [0:7];\n    reg [3:0] child_proc;\n    reg [31:0] f_coeff [0:8];\n    reg [31:0] g_coeff [0:8];\n    reg [31:0] temp_coeff [0:8];\n\n    reg [7:0] inv_int [0:8];\n    initial begin\n        inv_int[0] = 8'd0;\n        inv_int[1] = 8'd1;\n        inv_int[2] = 8'd0; // 1/2 mod MOD\n        inv_int[3] = 8'd0; // 1/3 mod MOD\n        inv_int[4] = 8'd0; // 1/4 mod MOD\n        inv_int[5] = 8'd0; // 1/5 mod MOD\n        inv_int[6] = 8'd0; // 1/6 mod MOD\n        inv_int[7] = 8'd0; // 1/7 mod MOD\n        inv_int[8] = 8'd0; // 1/8 mod MOD\n    end\n\n    integer i, j;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            node_idx <= 8'd0;\n            max_node <= 8'd0;\n            child_proc <= 4'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                child_cnt[i] <= 8'd0;\n                parents[i] <= 8'd0;\n                b_vals[i] <= 32'd0;\n                f_coeff[i] <= 32'd0;\n                g_coeff[i] <= 32'd0;\n                temp_coeff[i] <= 32'd0;\n            end\n            for (i = 0; i < 8; i = i + 1) begin\n                for (j = 0; j < 8; j = j + 1) begin\n                    children[i][j] <= 8'd0;\n                end\n            end\n        end else begin\n            state <= next_state;\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Load all inputs\n                        b_vals[0] <= b0;\n                        parents[0] <= p0;\n                        b_vals[1] <= b1;\n                        parents[1] <= p1;\n                        b_vals[2] <= b2;\n                        parents[2] <= p2;\n                        b_vals[3] <= b3;\n                        parents[3] <= p3;\n                        b_vals[4] <= b4;\n                        parents[4] <= p4;\n                        b_vals[5] <= b5;\n                        parents[5] <= p5;\n                        b_vals[6] <= b6;\n                        parents[6] <= p6;\n                        b_vals[7] <= b7;\n                        parents[7] <= p7;\n                        max_node <= (n > 8'd0) ? n - 8'd1 : 8'd0;\n                        node_idx <= 8'd0;\n                        next_state <= S_LOAD;\n                    end\n                end\n\n                S_LOAD: begin\n                    // Initialize child counters\n                    if (node_idx == 8'd0) begin\n                        for (i = 0; i < 8; i = i + 1) begin\n                            child_cnt[i] <= 8'd0;\n                        end\n                    end\n\n                    // Build child lists\n                    if (node_idx <= max_node) begin\n                        if (parents[node_idx] != 8'd255 && parents[node_idx] < 8'd8) begin\n                            children[parents[node_idx]][child_cnt[parents[node_idx]]] <= node_idx;\n                            child_cnt[parents[node_idx]] <= child_cnt[parents[node_idx]] + 8'd1;\n                        end\n                        node_idx <= node_idx + 8'd1;\n                    end else begin\n                        node_idx <= max_node; // Start topological sort\n                        next_state <= S_TOP;\n                    end\n                end\n\n                S_TOP: begin\n                    // Initialize polynomial f_v(x)\n                    f_coeff[0] <= 32'd1;\n                    for (i = 1; i < 9; i = i + 1) begin\n                        f_coeff[i] <= (i == 1) ? b_vals[node_idx] : 32'd0;\n                    end\n                    child_proc <= 4'd0;\n                    next_state <= S_PROCESS;\n                end\n\n                S_PROCESS: begin\n                    if (child_proc < child_cnt[node_idx]) begin\n                        // Multiply f_v = f_v * (1 + b_v * x * g_child)\n                        // Implement polynomial multiplication here\n                        for (i = 0; i < 9; i = i + 1) begin\n                            temp_coeff[i] <= f_coeff[i];\n                            f_coeff[i] <= 32'd0;\n                        end\n\n                        // Convolution\n                        for (i = 0; i < 9; i = i + 1) begin\n                            for (j = 0; j < 9; j = j + 1) begin\n                                if (i + j < 9) begin\n                                    f_coeff[i + j] <= (f_coeff[i + j] + (temp_coeff[i] * g_coeff[j])) % MOD;\n                                end\n                            end\n                        end\n\n                        child_proc <= child_proc + 4'd1;\n                    end else begin\n                        // Compute g_v(x) = ∫f_v(x) dx\n                        g_coeff[0] <= 32'd0;\n                        for (i = 0; i < 8; i = i + 1) begin\n                            g_coeff[i + 1] <= (f_coeff[i] * inv_int[i + 1]) % MOD;\n                        end\n\n                        if (node_idx == 8'd0) begin\n                            next_state <= S_COMPUTE;\n                        end else begin\n                            node_idx <= node_idx - 8'd1;\n                            next_state <= S_TOP;\n                        end\n                    end\n                end\n\n                S_COMPUTE: begin\n                    result <= g_coeff[1];  // Result initialization (simplified for example)\n                    next_state <= S_DONE;\n                end\n\n                S_DONE: begin\n                    done <= 1'b1;\n                    next_state <= S_IDLE;\n                end\n\n                default: next_state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule